css:
.qb-quote { font-family: sans-serif; margin: 12px 0; }
.qb-author { font-size: 0.85em; font-weight: bold; color: #0090ff; margin: 0 0 4px 12px; }
.qb-quote-text { display: inline-block; background: #0f3460; color: #fff; border-radius: 18px 18px 18px 4px; padding: 12px 16px; line-height: 1.45; white-space: pre-wrap; max-width: 85%; }
.qb-meta { font-size: 0.75em; color: #888; text-align: right; margin-top: 4px; }
.qb-rating { text-align: right; margin-top: 4px; color: #ffd54f; font-size: 0.9em; }
.qb-site-header { display: flex; justify-content: space-between; font-size: 0.75em; color: #777; margin-top: 8px; }
.qb-source-url { margin-top: 8px; font-size: 0.8em; }
.qb-source-url a { color: #0090ff; }
.qb-branding { margin-top: 10px; font-size: 0.75em; color: #666; text-align: center; }
